print(f"Fuel types: {sorted(df['fuel_type'].unique())}")
print(f"Date range: {df['recorded_at'].min()} to {df['recorded_at'].max()}")

# ── Helper: base64 encode a matplotlib figure ──────────────────
def fig_to_b64(fig=None, dpi=120):
    if fig is None:
        fig = plt.gcf()
    buf = BytesIO()
    fig.savefig(buf, format='png', dpi=dpi, bbox_inches='tight', facecolor='white')
    buf.seek(0)
    b64 = base64.b64encode(buf.read()).decode()
    plt.close(fig)
