})

# ── SECTION 1: Dataset Overview ─────────────────────────────────
print("Computing overview statistics...")
total_records = len(df)
total_records_feb = len(df_feb)
unique_stations = df['node_id'].nunique()
unique_stations_feb = df_feb['node_id'].nunique()
fuel_types = sorted(df['fuel_type'].unique())
date_min = df['recorded_at'].min().strftime('%d %B %Y')
date_max = df['recorded_at'].max().strftime('%d %B %Y')
date_min_feb = df_feb['recorded_at'].min().strftime('%d %B %Y') if len(df_feb) > 0 else 'N/A'
date_max_feb = df_feb['recorded_at'].max().strftime('%d %B %Y') if len(df_feb) > 0 else 'N/A'
null_counts = df.isnull().sum()
total_nulls = null_counts.sum()

# ── SECTION 2: Price Distribution by Fuel Type ──────────────────
print("Computing price distributions...")

# Use full dataset for richer statistics
fuel_stats = df.groupby('fuel_type').agg(
    mean_price=('price_pence', 'mean'),
    median_price=('price_pence', 'median'),
    min_price=('price_pence', 'min'),
    max_price=('price_pence', 'max'),
    std_price=('price_pence', 'std'),
    count=('price_pence', 'count'),
    q25=('price_pence', lambda x: x.quantile(0.25)),
    q75=('price_pence', lambda x: x.quantile(0.75)),
    station_count=('node_id', 'nunique'),
).reset_index()

fuel_stats['iqr'] = fuel_stats['q75'] - fuel_stats['q25']
fuel_stats['price_spread'] = fuel_stats['max_price'] - fuel_stats['min_price']
fuel_stats['mean_price_fmt'] = fuel_stats['mean_price'].apply(lambda x: f'£{x/100:.2f}')
fuel_stats['median_price_fmt'] = fuel_stats['median_price'].apply(lambda x: f'£{x/100:.2f}')
fuel_stats['min_price_fmt'] = fuel_stats['min_price'].apply(lambda x: f'£{x/100:.2f}')
fuel_stats['max_price_fmt'] = fuel_stats['max_price'].apply(lambda x: f'£{x/100:.2f}')
fuel_stats['iqr_fmt'] = fuel_stats['iqr'].apply(lambda x: f'{x:.1f}p')
fuel_stats['price_spread_fmt'] = fuel_stats['price_spread'].apply(lambda x: f'{x:.1f}p')
fuel_stats['std_fmt'] = fuel_stats['std_price'].apply(lambda x: f'{x:.2f}')

print(fuel_stats.to_string())

# ── Chart 1: Box plot of prices by fuel type ────────────────────
print("Generating charts...")
fig, ax = plt.subplots(figsize=(10, 6))
ordered_fuels = fuel_stats.sort_values('median_price')['fuel_type'].tolist()
plot_data = [df[df['fuel_type'] == ft]['price_pence'].dropna().values for ft in ordered_fuels]
