ax.yaxis.set_major_formatter(mticker.FormatStrFormatter('%d p'))
chart3_b64 = fig_to_b64(fig)

# ── SECTION 3: Price Spread Analysis ────────────────────────────
print("Computing price spread analysis...")

# ── Chart 4: Price range bars (min, IQR, max) ──────────────────
fig, ax = plt.subplots(figsize=(10, 6))
for i, (_, row) in enumerate(fuel_stats.iterrows()):
