def fmt_hours(h):
    """Format hours into readable string."""
    if pd.isna(h):
        return 'N/A'
    if h < 1:
        return f'{h*60:.0f} minutes'
    if h < 24:
        return f'{h:.1f} hours'
    days = h / 24
    return f'{days:.1f} days ({h:.0f} hours)'

