import matplotlib.ticker as mticker
import seaborn as sns
from io import BytesIO
import base64
from datetime import datetime

# ── Configuration ──────────────────────────────────────────────
DATA_PATH = '/app/benchmark/data.csv'
OUTPUT_PATH = '/app/output/final_report.html'
REPORT_DATE = 'February 2026'

# Professional colour palette — government/analyst-friendly
