fuel_stats['std_fmt'] = fuel_stats['std_price'].apply(lambda x: f'{x:.2f}')

print(fuel_stats.to_string())

# ── Chart 1: Box plot of prices by fuel type ────────────────────
print("Generating charts...")
fig, ax = plt.subplots(figsize=(10, 6))
ordered_fuels = fuel_stats.sort_values('median_price')['fuel_type'].tolist()
plot_data = [df[df['fuel_type'] == ft]['price_pence'].dropna().values for ft in ordered_fuels]
bp = ax.boxplot(plot_data, labels=ordered_fuels, patch_artist=True, widths=0.55,
                medianprops={'color': 'black', 'linewidth': 1.5},
                flierprops={'marker': 'o', 'markersize': 3, 'alpha': 0.4})
for patch, ft in zip(bp['boxes'], ordered_fuels):
    patch.set_facecolor(FUEL_COLORS.get(ft, '#999'))
